// Soil Moisture Monitor
// Lights an LED when soil moisture drops below a threshold.

const int SENSOR_PIN = A0;
const int LED_PIN = 9;

// Lower analogRead() values usually mean WETTER soil on these sensors.
// Tune this after watching real readings — see Troubleshooting.
const int DRY_THRESHOLD = 600;

void setup() {
  pinMode(LED_PIN, OUTPUT);
  Serial.begin(9600);
}

void loop() {
  int moistureLevel = analogRead(SENSOR_PIN);
  Serial.println(moistureLevel);

  if (moistureLevel > DRY_THRESHOLD) {
    digitalWrite(LED_PIN, HIGH); // too dry — needs water
  } else {
    digitalWrite(LED_PIN, LOW);
  }

  delay(1000);
}
